-- O que já existia vale como era: a assinatura da APR foi dada no aparelho do responsável (presencial), o encerramento já vinha
-- assinado, e só as APR 04, 05 e 06 têm a coluna "Assinatura" na folha de participantes (as demais só nome e matrícula).
UPDATE "apr_participante" SET "assinatura_presencial" = true WHERE "assinatura_path" IS NOT NULL;--> statement-breakpoint
UPDATE "execucao" SET "encerramento_assinado_em" = "fim" WHERE "resultado" = 'encerrada' AND "encerramento_assinado_em" IS NULL;--> statement-breakpoint
-- O modelo publicado é imutável (gatilho): a coluna nova é a única escrita, feita aqui com o gatilho desligado.
ALTER TABLE "modelo_apr" DISABLE TRIGGER "modelo_apr_publicado_imutavel";--> statement-breakpoint
UPDATE "modelo_apr" SET "participantes_com_assinatura" = false WHERE "codigo" IN ('APR 01', 'APR 02', 'APR 03', 'APR 07', 'APR 09');--> statement-breakpoint
ALTER TABLE "modelo_apr" ENABLE TRIGGER "modelo_apr_publicado_imutavel";
